export function normalizeImageSrc(src?: string | null): string {
  if (!src) return '';
  
  // Remove https://machinowa.tokyo prefix
  let normalized = src.replace(/^https?:\/\/machinowa\.tokyo/, '');
  
  // Remove query parameters and anchors
  normalized = normalized.split('?')[0].split('#')[0];
  
  // Decode if it's encoded
  try {
    normalized = decodeURIComponent(normalized);
  } catch {
    // If decoding fails, use the original
  }
  
  return normalized;
}

export function isBlockedImage(src?: string | null): boolean {
  if (!src) return false;
  
  const normalized = normalizeImageSrc(src);
  
  // Check both the normalized version and the original
  if (BLOCKED_IMAGE_SRCS.has(normalized)) return true;
  if (BLOCKED_IMAGE_SRCS.has(src)) return true;
  
  // Also check each blocked src in the set to account for encoding variations
  for (const blocked of BLOCKED_IMAGE_SRCS) {
    if (normalizeImageSrc(blocked) === normalized) return true;
  }
  
  return false;
}

export function sanitizeRestaurant(r: any): any {
  if (!r) return r;

  const result = { ...r };

  // Handle single image field
  if (result.image && isBlockedImage(result.image)) {
    result.image = null;
  }

  // Handle heroImages array
  if (result.heroImages && Array.isArray(result.heroImages)) {
    result.heroImages = result.heroImages.filter((img: string) => !isBlockedImage(img));
  }

  // Handle gallery array
  if (result.gallery && Array.isArray(result.gallery)) {
    result.gallery = result.gallery.filter((img: string) => !isBlockedImage(img));
  }

  // If image field is null/empty and we have heroImages, use the first one
  if ((!result.image || result.image === null) && result.heroImages && result.heroImages.length > 0) {
    result.image = result.heroImages[0];
  }

  // If both are empty, use a placeholder
  if (!result.image || result.image === null) {
    result.image = '/restaurants/_placeholder/feature-point.jpg';
  }

  return result;
}

export function sanitizeFeatureArticle(a: any): any {
  if (!a) return a;

  const result = { ...a };

  // Handle heroImage
  if (result.heroImage && isBlockedImage(result.heroImage)) {
    result.heroImage = '/restaurants/_placeholder/feature-hero.jpg';
  }

  // Handle ogImage
  if (result.ogImage && isBlockedImage(result.ogImage)) {
    result.ogImage = '/restaurants/_placeholder/feature-og.jpg';
  }

  // Handle ranking array with images
  if (result.ranking && Array.isArray(result.ranking)) {
    result.ranking = result.ranking.map((item: any) => {
      if (item.images && Array.isArray(item.images)) {
        const filtered = item.images.filter((img: string) => !isBlockedImage(img));
        return {
          ...item,
          images: filtered.length > 0 ? filtered : ['/restaurants/_placeholder/feature-point.jpg']
        };
      }
      return item;
    });
  }

  // Handle sideArticles
  if (result.sideArticles && Array.isArray(result.sideArticles)) {
    result.sideArticles = result.sideArticles.map((article: any) => {
      if (article.img && isBlockedImage(article.img)) {
        return {
          ...article,
          img: '/restaurants/_placeholder/feature-point.jpg'
        };
      }
      return article;
    });
  }

  return result;
}
